     uni.hideLoading()\r\n      uni.showToast({ title: '登录成功' })\r\n      setTimeout(() => uni.switchTab({ url: '/pages/index/index' }), 1000)\r\n    }).catch(err => {\r\n      uni.hideLoading()\r\n      uni.showToast({ title: err, icon: 'none' })\r\n    })\r\n  }).catch(() => {})\r\n}\r\n</script>\r\n\r\n<style lang=\"scss\" scoped>\r\n.login-page { padding: 60rpx; display: flex; flex-direction: column; align-items: center; justify-content: center; height: 100vh; }\r\n.brand { text-align: center; margin-bottom: 80rpx; }\r\n.logo { width: 160rpx; height: 160rpx; line-height: 160rpx; text-align: center; font-size: 60rpx; font-weight: bold; color: var(--pc-primary); margin: 0 auto 30rpx; background: var(--pc-card-bg); }\r\n.slogan { font-size: 36rpx; letter-spacing: 4rpx; }\r\n.form-box { width: 100%; padding: 40rpx; }\r\n.submit-btn { margin-top: 40rpx; width: 100%; }\r\n</style>","import MiniProgramPage from 'C:/Users/16947/CodeBuddy/MUST-Carpool-WeChat/MUST-GO/pages/login/login.vue'\nwx.createPage(MiniProgramPage)"],"names":["useUserStore","ref","uni"],"mappings":";;;;;;;;;;;;;;;;;;AA4BA,UAAM,YAAYA,YAAAA,aAAc;AAChC,UAAM,UAAUC,cAAG,IAAC,IAAI;AACxB,UAAM,WAAWA,cAAG,IAAC,EAAE,OAAO,eAAe,MAAM,IAAI;AAEvD,UAAM,QAAQ;AAAA,MACZ,OAAO,EAAE,OAAO,CAAC,EAAE,UAAU,MAAM,cAAc,UAAW,GAAE,EAAE,SAAS,kBAAkB,cAAc,QAAS,CAAA,EAAG;AAAA,MACrH,MAAM,EAAE,OAAO,CAAC,EAAE,UAAU,MAAM,cAAc,UAAS,CAAE,EAAG;AAAA,IAChE;AAEA,UAAM,WAAW,MAAMC,cAAG,MAAC,UAAU,EAAE,OAAO,gBAAgB,MAAM,QAAQ;AAE5E,UAAM,cAAc,MAAM;AACxB,cAAQ,MAAM,SAAU,EAAC,KAAK,MAAM;AAClCA,sBAAAA,MAAI,YAAY,EAAE,OAAO,MAAK,CAAE;AAChC,kBAAU,MAAM,SAAS,MAAM,OAAO,SAAS,MAAM,IAAI,EAAE,KAAK,MAAM;AACpEA,wBAAAA,MAAI,YAAa;AACjBA,wBAAAA,MAAI,UAAU,EAAE,OAAO,OAAM,CAAE;AAC/B,qBAAW,MAAMA,cAAAA,MAAI,UAAU,EAAE,KAAK,qBAAoB,CAAE,GAAG,GAAI;AAAA,QACzE,CAAK,EAAE,MAAM,SAAO;AACdA,wBAAAA,MAAI,YAAa;AACjBA,wBAAG,MAAC,UAAU,EAAE,OAAO,KAAK,MAAM,QAAQ;AAAA,QAChD,CAAK;AAAA,MACL,CAAG,EAAE,MAAM,MAAM;AAAA,OAAE;AAAA,IACnB;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;AClDA,GAAG,WAAW,eAAe;"}
